#include <bits/stdc++.h>
using namespace std;
bool isHappy(long long n){
    set<long long> seen;
    while(n!=1 && !seen.count(n)){
        seen.insert(n);
        long long s=0;
        while(n>0){ int d=n%10; s+=d*d; n/=10; }
        n=s;
    }
    return n==1;
}
int main(){
    int T; cin>>T;
    for(int tc=1;tc<=T;tc++){
        long long n; cin>>n;
        cout << "Case #" << tc << ": " << n << (isHappy(n)? " is a Happy number." : " is an Unhappy number.") << "\n";
    }
}

